/// <reference lib="webworker" />

import { quantizePixels, type PixelateOptions } from "./pixel-engine";

interface PixelWorkerRequest {
  pixels: ArrayBuffer;
  width: number;
  height: number;
  options: PixelateOptions;
}

self.onmessage = (event: MessageEvent<PixelWorkerRequest>) => {
  try {
    const { pixels, width, height, options } = event.data;
    const grid = quantizePixels(new Uint8ClampedArray(pixels), width, height, options);
    self.postMessage({ grid });
  } catch (error) {
    self.postMessage({ error: error instanceof Error ? error.message : "大图处理失败" });
  }
};
