// Pure pixel conversion shared by Web, its Worker, and the mini-program.
import { deltaE2000, rgbToLab, type Lab } from "./color-science";

export interface PixelColor { code: string; hex: string }

export interface PatternGrid {
  width: number;
  height: number;
  cells: Array<string | null>;
}

export interface PixelateOptions {
  size: number;
  maxColors: number;
  brightness: number;
  contrast: number;
  transparentBackground: boolean;
  preserveHardEdges?: boolean;
  crisp?: boolean;
  detailEnhancement?: number;
  ditherStrength?: number;
  palette?: PixelColor[];
}

export function hexToRgb(hex: string): [number, number, number] {
  const value = Number.parseInt(hex.slice(1), 16);
  return [(value >> 16) & 255, (value >> 8) & 255, value & 255];
}

interface PreparedColor<T> { color: T; lab: Lab }

/** Exact CIEDE2000 ranking across every supplied colour, cached by the complete input. */
export function createPixelPaletteMatcher<T extends PixelColor>(colors: T[]): (r: number, g: number, b: number) => T {
  if (!colors.length) throw new Error("当前条件下没有可用颜色");
  const prepared: PreparedColor<T>[] = colors.map((color) => {
    const rgb = hexToRgb(color.hex);
    return { color, lab: rgbToLab(...rgb) };
  });
  const cache = new Map<string, T>();
  return (r, g, b) => {
    const key = `${r}:${g}:${b}`;
    const cached = cache.get(key);
    if (cached) return cached;
    const lab = rgbToLab(r, g, b);
    let best = prepared[0]!;
    let bestDistance = Number.POSITIVE_INFINITY;
    for (const candidate of prepared) {
      const distance = deltaE2000(lab, candidate.lab);
      if (distance < bestDistance) { best = candidate; bestDistance = distance; }
    }
    cache.set(key, best.color);
    return best.color;
  };
}
function clamp(value: number): number {
  return Math.max(0, Math.min(255, value));
}

function enhanceDetails(data: Uint8ClampedArray, width: number, height: number, amount: number): Uint8ClampedArray {
  const strength = Math.max(0, Math.min(1, amount));
  if (strength === 0 || width < 3 || height < 3) return data;
  const result = new Uint8ClampedArray(data);
  const sharpen = .35 + strength * .9;
  for (let y = 1; y < height - 1; y += 1) {
    for (let x = 1; x < width - 1; x += 1) {
      const index = (y * width + x) * 4;
      if (data[index + 3] < 80) continue;
      for (let channel = 0; channel < 3; channel += 1) {
        const blur = (
          data[index - width * 4 + channel]
          + data[index + width * 4 + channel]
          + data[index - 4 + channel]
          + data[index + 4 + channel]
        ) / 4;
        result[index + channel] = clamp(data[index + channel] + (data[index + channel] - blur) * sharpen);
      }
    }
  }
  return result;
}

export function quantizePixels(
  data: Uint8ClampedArray,
  width: number,
  height: number,
  options: PixelateOptions,
): PatternGrid {
  const palette = options.palette ?? [];
  if (!palette.length) throw new Error("尚未加载可用色卡");
  const enhanced = options.preserveHardEdges
    ? data
    : enhanceDetails(data, width, height, options.detailEnhancement ?? (options.crisp ? .55 : 0));
  const pixelCount = width * height;
  const adjusted = new Float32Array(pixelCount * 3);
  const visible = new Uint8Array(pixelCount);
  const usage = new Map<string, number>();
  const effectiveContrast = Math.max(-100, Math.min(100, options.contrast + (options.crisp ? 10 : 0)));
  const factor = (259 * (effectiveContrast + 255)) / (255 * (259 - effectiveContrast));
  const cells: Array<string | null> = [];
  const paletteMatcher = createPixelPaletteMatcher(palette);
  for (let index = 0, pixel = 0; index < enhanced.length; index += 4, pixel += 1) {
    if (options.transparentBackground && enhanced[index + 3] < 80) {
      continue;
    }
    const r = clamp(factor * (enhanced[index] - 128) + 128 + options.brightness);
    const g = clamp(factor * (enhanced[index + 1] - 128) + 128 + options.brightness);
    const b = clamp(factor * (enhanced[index + 2] - 128) + 128 + options.brightness);
    visible[pixel] = 1;
    adjusted[pixel * 3] = r;
    adjusted[pixel * 3 + 1] = g;
    adjusted[pixel * 3 + 2] = b;
    const nearest = paletteMatcher(r, g, b);
    usage.set(nearest.code, (usage.get(nearest.code) ?? 0) + 1);
  }
  const selectedCodes = [...usage.entries()]
    .sort((left, right) => right[1] - left[1])
    .slice(0, Math.max(2, options.maxColors))
    .map(([code]) => code);
  const colors = selectedCodes.length
    ? palette.filter((color) => selectedCodes.includes(color.code))
    : palette.slice(0, Math.max(1, options.maxColors));
  const ditherStrength = Math.max(0, Math.min(.6, options.ditherStrength ?? 0));
  const selectedMatcher = createPixelPaletteMatcher(colors);
  if (ditherStrength === 0) {
    for (let pixel = 0; pixel < pixelCount; pixel += 1) {
      const offset = pixel * 3;
      cells.push(visible[pixel]
        ? selectedMatcher(adjusted[offset], adjusted[offset + 1], adjusted[offset + 2]).code
        : null);
    }
  } else {
    const work = adjusted.slice();
    const rgbByCode = new Map(colors.map((color) => [color.code, color.hex.match(/[a-f\d]{2}/gi)!.map((part) => Number.parseInt(part, 16))]));
    const spread = (x: number, y: number, error: [number, number, number], weight: number) => {
      if (x < 0 || y < 0 || x >= width || y >= height) return;
      const pixel = y * width + x;
      if (!visible[pixel]) return;
      const offset = pixel * 3;
      for (let channel = 0; channel < 3; channel += 1) work[offset + channel] = clamp(work[offset + channel] + error[channel] * weight * ditherStrength);
    };
    for (let y = 0; y < height; y += 1) {
      for (let x = 0; x < width; x += 1) {
        const index = y * width + x;
        if (!visible[index]) { cells.push(null); continue; }
        const offset = index * 3;
        const nearest = selectedMatcher(work[offset], work[offset + 1], work[offset + 2]);
        cells.push(nearest.code);
        const matched = rgbByCode.get(nearest.code) ?? [work[offset], work[offset + 1], work[offset + 2]];
        const error: [number, number, number] = [work[offset] - matched[0], work[offset + 1] - matched[1], work[offset + 2] - matched[2]];
        spread(x + 1, y, error, 7 / 16);
        spread(x - 1, y + 1, error, 3 / 16);
        spread(x, y + 1, error, 5 / 16);
        spread(x + 1, y + 1, error, 1 / 16);
      }
    }
  }
  return { width, height, cells };
}

